import React from 'react';
import { Container, Row, Col, Card, CardBody } from 'reactstrap';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import useFetch from '../../hooks/useFetch';
import { BASE_URL } from '../../utils/config';

const Dashboard = () => {
    const { data: bookings, loading } = useFetch(`${BASE_URL}/booking`);

    // --- LOGIC XỬ LÝ THỐNG KÊ ---
    
    // 1. Tính doanh thu hôm nay
    const today = new Date().toLocaleDateString('vi-VN');
    const revenueToday = bookings?.filter(item => 
        new Date(item.createdAt).toLocaleDateString('vi-VN') === today
    ).reduce((acc, curr) => acc + (curr.totalPrice || 0), 0) || 0;

    // 2. Tính doanh thu tháng này
    const thisMonth = new Date().getMonth();
    const thisYear = new Date().getFullYear();
    const revenueMonth = bookings?.filter(item => {
        const d = new Date(item.createdAt);
        return d.getMonth() === thisMonth && d.getFullYear() === thisYear;
    }).reduce((acc, curr) => acc + (curr.totalPrice || 0), 0) || 0;

    // 3. Chuẩn bị dữ liệu cho biểu đồ (7 ngày gần nhất)
    const chartData = bookings?.reduce((acc, item) => {
        const date = new Date(item.createdAt).toLocaleDateString('vi-VN', {day: '2-digit', month: '2-digit'});
        const existingDate = acc.find(d => d.name === date);
        if (existingDate) {
            existingDate.total += item.totalPrice || 0;
        } else {
            acc.push({ name: date, total: item.totalPrice || 0 });
        }
        return acc;
    }, []).slice(-7); // Lấy 7 ngày gần đây nhất

    return (
        <section>
            <Container>
                <Row>
                    <Col lg='12'><h3 className="mb-4">Thống kê doanh thu</h3></Col>
                    
                    {/* Thẻ thống kê nhanh */}
                    <Col lg='4'>
                        <Card className="bg-primary text-white border-0 shadow-sm mb-4">
                            <CardBody>
                                <h6>Doanh thu hôm nay ({today})</h6>
                                <h4>{revenueToday.toLocaleString('vi-VN')}đ</h4>
                            </CardBody>
                        </Card>
                    </Col>
                    <Col lg='4'>
                        <Card className="bg-info text-white border-0 shadow-sm mb-4">
                            <CardBody>
                                <h6>Tháng {thisMonth + 1}/{thisYear}</h6>
                                <h4>{revenueMonth.toLocaleString('vi-VN')}đ</h4>
                            </CardBody>
                        </Card>
                    </Col>
                    <Col lg='4'>
                        <Card className="bg-success text-white border-0 shadow-sm mb-4">
                            <CardBody>
                                <h6>Tổng đơn hàng</h6>
                                <h4>{bookings?.length || 0} đơn</h4>
                            </CardBody>
                        </Card>
                    </Col>
                </Row>

                {/* Biểu đồ doanh thu */}
                <Row className="mt-4">
                    <Col lg='12'>
                        <Card className="p-4 shadow-sm border-0">
                            <h5>Biểu đồ doanh thu 7 ngày gần nhất</h5>
                            <div style={{ width: '100%', height: 300 }}>
                                <ResponsiveContainer>
                                    <BarChart data={chartData}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                        <XAxis dataKey="name" />
                                        <YAxis tickFormatter={(value) => `${value / 1000000}M`} />
                                        <Tooltip formatter={(value) => [value.toLocaleString('vi-VN') + "đ", "Doanh thu"]} />
                                        <Bar dataKey="total" fill="#4e73df" radius={[4, 4, 0, 0]} barSize={40} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </Card>
                    </Col>
                </Row>
            </Container>
        </section>
    );
};

export default Dashboard;
